+  ));
+}
+
+function summarizePackets(contextPackets) {
+  const packs = contextPackets.map((packet) => packet.evidence_context_pack).filter(isObject);
+  const semanticContextCounts = countBy(packs, 'semantic_context');
+  const includedAssertionCount = packs.reduce((sum, pack) => (
+    sum + (Array.isArray(pack.assertions) ? pack.assertions.length : 0)
+  ), 0);
+  const excludedAssertionCount = packs.reduce((sum, pack) => (
+    sum + (Array.isArray(pack.excluded_assertions) ? pack.excluded_assertions.length : 0)
+  ), 0);
+  const fallbackPacketCount = contextPackets.filter((packet) => (
+    packet.packet_kind === 'fallback_fixture' ||
+    packet.evidence_context_pack?.semantic_context === 'provisional_degraded'
+  )).length;
+
+  return {
+    packet_count: contextPackets.length,
+    semantic_slice_packet_count: contextPackets.filter((packet) => (
+      packet.packet_kind?.startsWith('semantic_slice_')
+    )).length,
+    fallback_packet_count: fallbackPacketCount,
+    unavailable_fallback_packet_count: packs.filter((pack) => (
+      pack.semantic_context === 'unavailable'
+    )).length,
+    provisional_degraded_packet_count: semanticContextCounts.provisional_degraded ?? 0,
+    available_verified_packet_count: semanticContextCounts.available_verified ?? 0,
+    blocked_excluded_packet_count: semanticContextCounts.blocked_excluded ?? 0,
+    included_assertion_count: includedAssertionCount,
+    excluded_assertion_count: excludedAssertionCount,
+    semantic_context_counts: semanticContextCounts,
+  };
+}
+
+function buildPacketPilot({ root, paths, generatedAt, inputs }) {
+  const acceptedAssertions = safeAssertionsFrom(inputs.acceptedDelta.assertions, 'accepted');
+  const provisionalAssertions = safeAssertionsFrom(
+    inputs.provisionalSafeDelta.assertions,
+    'provisional_safe',
+  );
+  const excludedAssertions = [
+    ...unsafeAssertionsFrom(inputs.acceptedDelta.assertions),
+    ...unsafeAssertionsFrom(inputs.provisionalSafeDelta.assertions),
+  ];
+  const rowPackets = PILOT_ROW_IDS.map((rowId) => buildRowPacket({
+    root,
+    paths,
+    rowId,
+    acceptedAssertions,
+    provisionalAssertions,
+    excludedAssertions,
+  }));
+  const fallbackPackets = FALLBACK_FIXTURE_IDS
+    .map((fixtureId) => fixtureById(inputs.evidenceContextPackFixtures, fixtureId))
+    .filter((fixture) => isObject(fixture?.pack))
+    .map((fixture) => buildFallbackPacket({ root, paths, fixture }));
+  const contextPackets = [...rowPackets, ...fallbackPackets];
+  const summary = summarizePackets(contextPackets);
+  const sourceContract = {
+    checked_in_artifacts_only: true,
+    validated_semantic_slice_path: paths.ragLiteHvy01ValidatorIn,
+    evidence_context_pack_schema_path: paths.evidenceContextPackSchemaIn,
+    evidence_context_pack_fixtures_path: paths.evidenceContextPackFixturesIn,
+    production_rag_reindex_count: 0,
+    vector_mutation_count: 0,
+    remote_supabase_mutation: false,
+    runtime_answer_generation_count: 0,
+    external_model_call_count: 0,
+  };
+
+  const packetPilot = {
+    schema_version: PACKET_PILOT_SCHEMA_VERSION,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    upstream_issues: [...UPSTREAM_ISSUES],
+    subject_code: SUBJECT_CODE,
+    objective:
+      'Generate dry-run retrieval/context packets from the validated semantic KG slice without mutating retrieval stores.',
+    pilot_selection: {
+      row_ids: [...PILOT_ROW_IDS],
+      fallback_fixture_ids: [...FALLBACK_FIXTURE_IDS],
+      selection_policy:
+        'small deterministic semantic slice covering available_verified, provisional_degraded, and unavailable fallback packets',
+    },
+    source_contract: sourceContract,
+    no_mutation_readback: {
+      production_rag_reindex: 0,
+      vector_mutations: 0,
+      remote_supabase_mutation: false,
