+}
+
+function validatePacket({ packet, evidenceContextPackSchema }) {
+  const errors = [];
+  const packetId = packet?.packet_id ?? 'unknown';
+  const pack = packet?.evidence_context_pack;
+  if (!isObject(pack)) return [`${packetId}:evidence_context_pack_missing`];
