+      errors.push(`${packetId}:provisional_degraded_rendered_as_certain_fact`);
+    }
+    if (!pack.downgrade_instructions?.includes('do_not_render_as_certain_fact')) {
+      errors.push(`${packetId}:provisional_degraded_missing_downgrade`);
+    }
+  }
