+      errors.push(`${packetId}:fallback_packet_blocks_question_attempt`);
+    }
+    if (semanticFactCount(pack.semantic_fact_projection) !== 0) {
+      errors.push(`${packetId}:fallback_packet_invents_semantic_facts`);
+    }
+    if (pack.fallback_behavior?.enabled !== true) {
+      errors.push(`${packetId}:fallback_packet_missing_enabled_fallback`);
+    }
