+      JSON.stringify(FALLBACK_ALLOWED_SOURCES)) {
+      errors.push(`${packetId}:fallback_allowed_sources_invalid`);
+    }
+    if (JSON.stringify(pack.fallback_behavior?.no_invention_constraints) !==
+      JSON.stringify(NO_INVENTION_CONSTRAINTS)) {
+      errors.push(`${packetId}:fallback_no_invention_constraints_invalid`);
+    }
+  }
+
+  if (!Array.isArray(packet?.source_artifact_refs) || packet.source_artifact_refs.length === 0 ||
+    !packet.source_artifact_refs.every((ref) => ref?.exists === true && hasString(ref?.sha256))) {
+    errors.push(`${packetId}:source_artifact_refs_missing`);
+  }
+  if (!isObject(packet?.status_summary) || !hasString(pack.status)) {
+    errors.push(`${packetId}:status_summary_missing`);
+  }
+  if (!Array.isArray(pack.downgrade_instructions) || pack.downgrade_instructions.length === 0) {
+    errors.push(`${packetId}:downgrade_instructions_missing`);
+  }
+
+  return errors;
+}
