+  const errors = [];
+  const contextPackets = Array.isArray(packetPilot?.context_packets)
+    ? packetPilot.context_packets
+    : [];
+  const packetErrors = contextPackets.flatMap((packet) => (
+    validatePacket({ packet, evidenceContextPackSchema })
+  ));
+  errors.push(...packetErrors);
+
+  if (contextPackets.length === 0) errors.push('dry_run_packets_missing');
+  if (packetPilot?.source_contract?.checked_in_artifacts_only !== true) {
+    errors.push('non_checked_in_source_contract');
+  }
+  const readback = packetPilot?.no_mutation_readback;
+  if (readback?.production_rag_reindex !== 0 ||
