+    packetPilot?.source_contract?.vector_mutation_count !== 0 ||
+    packetPilot?.source_contract?.remote_supabase_mutation !== false) {
+    errors.push('no_mutation_readback_drift');
+  }
+
+  const hasFallback = contextPackets.some((packet) => (
+    packet.packet_kind === 'fallback_fixture' ||
+    packet.evidence_context_pack?.semantic_context === 'provisional_degraded'
+  ));
+  if (!hasFallback) errors.push('fallback_packet_missing');
+
+  const checks = [
+    {
+      id: 'dry_run_packets_exist',
+      status: contextPackets.length > 0 ? 'pass' : 'fail',
